// Stands in for a component library that provides a context of its own, which openstate must leave out.
import { createContext, createElement, type ReactNode } from "react"

export const LibContext = createContext({ theme: "light" })

export let renders = 0

// Not a tail call (the finally sees to it), as JavaScriptCore would drop the component's frame: see test/react.test.ts.
export function LibProvider({ children }: { children?: ReactNode }) {
  try {
    return createElement(LibContext, { value: { theme: "dark" } }, children)
  } finally {
    renders++
  }
}
